import{_ as e,o as a,c as r,a2 as i}from"./chunks/framework.CDpkVv68.js";const m=JSON.parse('{"title":"Familiarity and practice","description":"","frontmatter":{},"headers":[],"relativePath":"en/guide/characters/familiarity.md","filePath":"en/guide/characters/familiarity.md"}'),n={name:"en/guide/characters/familiarity.md"};function d(l,t,s,o,c,h){return a(),r("div",null,[...t[0]||(t[0]=[i('<h1 id="familiarity-and-practice" tabindex="-1">Familiarity and practice <a class="header-anchor" href="#familiarity-and-practice" aria-label="Permalink to &quot;Familiarity and practice&quot;">​</a></h1><p><strong>Status:</strong> Proposed shared tiers · Experimental martial modifiers and retention · Not implemented.</p><h2 id="tl-dr" tabindex="-1">TL;DR <a class="header-anchor" href="#tl-dr" aria-label="Permalink to &quot;TL;DR&quot;">​</a></h2><ul><li>Learning preserves knowledge; practice improves execution through Learned, Practiced and Mastered.</li><li>Experimental martial retention counts active play days, not calendar absence.</li><li>Prepared options and fluency are separate; martial modifiers do not assign spell numbers.</li></ul><p>Learning gives permanent knowledge; practice improves fluency. Time away does not erase techniques.</p><h2 id="at-a-glance" tabindex="-1">At a glance <a class="header-anchor" href="#at-a-glance" aria-label="Permalink to &quot;At a glance&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Martial SA tier</th><th>Stamina / recovery</th><th>Accuracy</th><th>Defensive window</th></tr></thead><tbody><tr><td>Learned</td><td>+5% / +5%</td><td>−2 pp</td><td>−5%</td></tr><tr><td>Practiced</td><td>Normal</td><td>Normal</td><td>Normal</td></tr><tr><td>Mastered</td><td>−3% / −3%</td><td>+1 pp</td><td>+5%</td></tr></tbody></table><p>No raw-damage bonus. These Experimental martial values do not assign spell costs or casting times; spells share the tier names only. Basics remain neutral.</p><h2 id="maintenance-test" tabindex="-1">Maintenance test <a class="header-anchor" href="#maintenance-test" aria-label="Permalink to &quot;Maintenance test&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Retain</th><th>World uses</th><th>Or training</th></tr></thead><tbody><tr><td>Mastered</td><td>20</td><td>5 repetitions</td></tr><tr><td>Practiced</td><td>9</td><td>3 repetitions</td></tr><tr><td>Learned</td><td>None</td><td>Permanent floor</td></tr></tbody></table><ul><li>Counts use the last 7 active days, not calendar days away.</li><li>Test active day: at least 10 minutes of non-idle play on a UTC date.</li><li>Only meaningful, qualifying uses count; exercise and abuse rules still need testing.</li><li>Either world or training threshold must be met; mixing them has no exchange rate yet.</li><li>Evaluation starts after 7 active days since learning/tier gain and drops at most one tier per active-day check.</li><li>These are retention rules. How to gain tiers remains unresolved.</li></ul><h2 id="training-and-preparation" tabindex="-1">Training and preparation <a class="header-anchor" href="#training-and-preparation" aria-label="Permalink to &quot;Training and preparation&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Support</th><th>Purpose</th></tr></thead><tbody><tr><td>Dummies / ranges / practice halls</td><td>Maintain fluency efficiently</td></tr><tr><td>Carpentry / Tinkering / Inscription</td><td>Candidate facility equipment and materials</td></tr><tr><td>5 prepared SA slots</td><td>Ready options, not all known techniques</td></tr></tbody></table><p>Facilities are not intended as the best core-skill grind or a discovery bypass. Prepared techniques receive no special decay protection in this first test.</p><h2 id="example" tabindex="-1">Example <a class="header-anchor" href="#example" aria-label="Permalink to &quot;Example&quot;">​</a></h2><p>An absent swordsman returns with the same knowledge and no new active days counted. During continued play, neglected fluency can fall toward Learned, never Unknown.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><p><a href="/Syrolands-Public/en/guide/combat/special-attacks.html">Special Attacks</a> · <a href="/Syrolands-Public/en/guide/magic/memory-and-familiarity.html">Spell Memory</a> · <a href="/Syrolands-Public/en/game-design/characters/familiarity.html">Full design</a> · <a href="/Syrolands-Public/en/game-design/combat/numeric-prototype.html#maintenance-test">Exact test rules</a></p>',18)])])}const u=e(n,[["render",d]]);export{m as __pageData,u as default};
